   443→/// Complete kzg verification for a `DataColumnSidecar`.
   444→///
   445→/// Returns an error if the kzg verification check fails.
   446→#[instrument(skip_all, level = "debug")]
   447→pub fn verify_kzg_for_data_column<E: EthSpec>(
   448→    data_column: Arc<DataColumnSidecar<E>>,
   449→    kzg: &Kzg,
   450→) -> Result<KzgVerifiedDataColumn<E>, (Option<ColumnIndex>, KzgError)> {
   451→    let _timer = metrics::start_timer(&metrics::KZG_VERIFICATION_DATA_COLUMN_SINGLE_TIMES);
   452→    validate_data_columns(kzg, iter::once(&data_column))?;
   453→    Ok(KzgVerifiedDataColumn { data: data_column })
   454→}
   455→
   456→/// Complete kzg verification for a list of `DataColumnSidecar`s.
   457→/// Returns an error for the first `DataColumnSidecar`s that fails kzg verification.
   458→///
   459→/// Note: This function should be preferred over calling `verify_kzg_for_data_column`
   460→/// in a loop since this function kzg verifies a list of data columns more efficiently.
   461→pub fn verify_kzg_for_data_column_list<'a, E: EthSpec, I>(
   462→    data_column_iter: I,
   463→    kzg: &'a Kzg,
   464→) -> Result<(), (Option<ColumnIndex>, KzgError)>
   465→where
   466→    I: Iterator<Item = &'a Arc<DataColumnSidecar<E>>> + Clone,
   467→{
   468→    let _timer = metrics::start_timer(&metrics::KZG_VERIFICATION_DATA_COLUMN_BATCH_TIMES);
   469→    validate_data_columns(kzg, data_column_iter)?;
   470→    Ok(())
   471→}
   472→
   473→#[instrument(skip_all, level = "debug")]
   474→pub fn validate_data_column_sidecar_for_gossip<T: BeaconChainTypes, O: ObservationStrategy>(
   475→    data_column: Arc<DataColumnSidecar<T::EthSpec>>,
   476→    subnet: DataColumnSubnetId,
   477→    chain: &BeaconChain<T>,
   478→) -> Result<GossipVerifiedDataColumn<T, O>, GossipDataColumnError> {
   479→    let column_slot = data_column.slot();
   480→    verify_data_column_sidecar(&data_column)?;
   481→    verify_index_matches_subnet(&data_column, subnet, &chain.spec)?;
   482→    verify_sidecar_not_from_future_slot(chain, column_slot)?;
   483→    verify_slot_greater_than_latest_finalized_slot(chain, column_slot)?;
   484→    verify_is_unknown_sidecar(chain, &data_column)?;
   485→
   486→    // Check if the data column is already in the DA checker cache. This happens when data columns
   487→    // are made available through the `engine_getBlobs` method.  If it exists in the cache, we know
   488→    // it has already passed the gossip checks, even though this particular instance hasn't been
   489→    // seen / published on the gossip network yet (passed the `verify_is_unknown_sidecar` check above).
   490→    // In this case, we should accept it for gossip propagation.
   491→    if chain
   492→        .data_availability_checker
   493→        .is_data_column_cached(&data_column.block_root(), &data_column)
   494→    {
   495→        // Observe this data column so we don't process it again.
   496→        if O::observe() {
   497→            observe_gossip_data_column(&data_column, chain)?;
   498→        }
   499→        return Err(GossipDataColumnError::PriorKnownUnpublished);
   500→    }
   501→
   502→    verify_column_inclusion_proof(&data_column)?;
   503→    let parent_block = verify_parent_block_and_finalized_descendant(data_column.clone(), chain)?;
   504→    verify_slot_higher_than_parent(&parent_block, column_slot)?;
   505→    verify_proposer_and_signature(&data_column, &parent_block, chain)?;
   506→    let kzg = &chain.kzg;
   507→    let kzg_verified_data_column = verify_kzg_for_data_column(data_column.clone(), kzg)
   508→        .map_err(|(_, e)| GossipDataColumnError::InvalidKzgProof(e))?;
   509→
   510→    chain
   511→        .observed_slashable
   512→        .write()
   513→        .observe_slashable(
   514→            column_slot,
   515→            data_column.block_proposer_index(),
   516→            data_column.block_root(),
   517→        )
   518→        .map_err(|e| GossipDataColumnError::BeaconChainError(Box::new(e.into())))?;
   519→
   520→    if O::observe() {
   521→        observe_gossip_data_column(&data_column, chain)?;
   522→    }
   523→
   524→    Ok(GossipVerifiedDataColumn {
   525→        block_root: data_column.block_root(),
   526→        data_column: kzg_verified_data_column,
   527→        _phantom: PhantomData,
   528→    })
   529→}
   530→
   531→/// Verify if the data column sidecar is valid.
   532→fn verify_data_column_sidecar<E: EthSpec>(
   533→    data_column: &DataColumnSidecar<E>,
   534→) -> Result<(), GossipDataColumnError> {
   535→    if data_column.index >= E::number_of_columns() as u64 {
   536→        return Err(GossipDataColumnError::InvalidColumnIndex(data_column.index));
   537→    }
   538→    if data_column.kzg_commitments.is_empty() {
   539→        return Err(GossipDataColumnError::UnexpectedDataColumn);
   540→    }
   541→
   542→    let cells_len = data_column.column.len();
   543→    let commitments_len = data_column.kzg_commitments.len();
   544→    let proofs_len = data_column.kzg_proofs.len();
   545→
   546→    if cells_len != commitments_len {
   547→        return Err(GossipDataColumnError::InconsistentCommitmentsLength {
   548→            cells_len,
   549→            commitments_len,
   550→        });
   551→    }
   552→
   553→    if cells_len != proofs_len {
   554→        return Err(GossipDataColumnError::InconsistentProofsLength {
   555→            cells_len,
   556→            proofs_len,
   557→        });
   558→    }
   559→
   560→    Ok(())
   561→}
   562→
   563→/// Verify that `column_sidecar` is not yet known, i.e. this is the first time `column_sidecar` has been received for the tuple:
   564→/// `(block_header.slot, block_header.proposer_index, column_sidecar.index)`
   565→fn verify_is_unknown_sidecar<T: BeaconChainTypes>(
   566→    chain: &BeaconChain<T>,
   567→    column_sidecar: &DataColumnSidecar<T::EthSpec>,
   568→) -> Result<(), GossipDataColumnError> {
   569→    if chain
   570→        .observed_column_sidecars
   571→        .read()
   572→        .proposer_is_known(column_sidecar)
   573→        .map_err(|e| GossipDataColumnError::BeaconChainError(Box::new(e.into())))?
   574→    {
   575→        return Err(GossipDataColumnError::PriorKnown {
   576→            proposer: column_sidecar.block_proposer_index(),
   577→            slot: column_sidecar.slot(),
   578→            index: column_sidecar.index,
   579→        });
   580→    }
   581→    Ok(())
   582→}
   583→
   584→fn verify_column_inclusion_proof<E: EthSpec>(
   585→    data_column: &DataColumnSidecar<E>,
   586→) -> Result<(), GossipDataColumnError> {
   587→    let _timer = metrics::start_timer(&metrics::DATA_COLUMN_SIDECAR_INCLUSION_PROOF_VERIFICATION);
   588→    if !data_column.verify_inclusion_proof() {
   589→        return Err(GossipDataColumnError::InvalidInclusionProof);
   590→    }
   591→
   592→    Ok(())
   593→}
   594→
   595→fn verify_slot_higher_than_parent(
   596→    parent_block: &Block,
   597→    data_column_slot: Slot,
   598→) -> Result<(), GossipDataColumnError> {
   599→    if parent_block.slot >= data_column_slot {
   600→        return Err(GossipDataColumnError::IsNotLaterThanParent {
   601→            data_column_slot,
   602→            parent_slot: parent_block.slot,
   603→        });
   604→    }
   605→    Ok(())
   606→}
   607→
   608→fn verify_parent_block_and_finalized_descendant<T: BeaconChainTypes>(
   609→    data_column: Arc<DataColumnSidecar<T::EthSpec>>,
   610→    chain: &BeaconChain<T>,
   611→) -> Result<ProtoBlock, GossipDataColumnError> {
   612→    let fork_choice = chain.canonical_head.fork_choice_read_lock();
   613→
   614→    // We have already verified that the column is past finalization, so we can
   615→    // just check fork choice for the block's parent.
   616→    let block_parent_root = data_column.block_parent_root();
   617→    let Some(parent_block) = fork_choice.get_block(&block_parent_root) else {
   618→        return Err(GossipDataColumnError::ParentUnknown {
   619→            parent_root: block_parent_root,
   620→        });
   621→    };
   622→
   623→    // Do not process a column that does not descend from the finalized root.
   624→    // We just loaded the parent_block, so we can be sure that it exists in fork choice.
   625→    if !fork_choice.is_finalized_checkpoint_or_descendant(block_parent_root) {
   626→        return Err(GossipDataColumnError::NotFinalizedDescendant { block_parent_root });
   627→    }
   628→
   629→    Ok(parent_block)
   630→}
   631→
   632→fn verify_proposer_and_signature<T: BeaconChainTypes>(
   633→    data_column: &DataColumnSidecar<T::EthSpec>,
   634→    parent_block: &ProtoBlock,
   635→    chain: &BeaconChain<T>,
   636→) -> Result<(), GossipDataColumnError> {
   637→    let column_slot = data_column.slot();
   638→    let slots_per_epoch = T::EthSpec::slots_per_epoch();
   639→    let column_epoch = column_slot.epoch(slots_per_epoch);
   640→    let column_index = data_column.index;
   641→    let block_root = data_column.block_root();
   642→    let block_parent_root = data_column.block_parent_root();
   643→
   644→    let proposer_shuffling_root = if parent_block.slot.epoch(slots_per_epoch) == column_epoch {
   645→        parent_block
   646→            .next_epoch_shuffling_id
   647→            .shuffling_decision_block
   648→    } else {
   649→        parent_block.root
   650→    };
   651→
   652→    // We lock the cache briefly to get or insert a OnceCell, then drop the lock
   653→    // before doing proposer shuffling calculation via `OnceCell::get_or_try_init`. This avoids
   654→    // holding the lock during the computation, while still ensuring the result is cached and
   655→    // initialised only once.
   656→    //
   657→    // This approach exposes the cache internals (`OnceCell` & `EpochBlockProposers`)
   658→    //  as a trade-off for avoiding lock contention.
   659→    let epoch_proposers_cell = chain
   660→        .beacon_proposer_cache
   661→        .lock()
   662→        .get_or_insert_key(column_epoch, proposer_shuffling_root);
   663→
   664→    let epoch_proposers = epoch_proposers_cell.get_or_try_init(move || {
   665→        debug!(
   666→            %block_root,
   667→            index = %column_index,
   668→            "Proposer shuffling cache miss for column verification"
   669→        );
   670→        let (parent_state_root, mut parent_state) = chain
   671→            .store
   672→            .get_advanced_hot_state(block_parent_root, column_slot, parent_block.state_root)
   673→            .map_err(|e| GossipDataColumnError::BeaconChainError(Box::new(e.into())))?
   674→            .ok_or_else(|| {
   675→                BeaconChainError::DBInconsistent(format!(
   676→                    "Missing state for parent block {block_parent_root:?}",
   677→                ))
   678→            })?;
   679→
   680→        let state = cheap_state_advance_to_obtain_committees::<_, GossipDataColumnError>(
   681→            &mut parent_state,
   682→            Some(parent_state_root),
   683→            column_slot,
   684→            &chain.spec,
   685→        )?;
   686→
   687→        let epoch = state.current_epoch();
   688→        let proposers = state.get_beacon_proposer_indices(epoch, &chain.spec)?;
   689→        // Prime the proposer shuffling cache with the newly-learned value.
   690→        Ok::<_, GossipDataColumnError>(EpochBlockProposers {
   691→            epoch: column_epoch,
   692→            fork: state.fork(),
   693→            proposers: proposers.into(),
   694→        })
   695→    })?;
   696→
   697→    let proposer_index = *epoch_proposers
   698→        .proposers
   699→        .get(column_slot.as_usize() % slots_per_epoch as usize)
   700→        .ok_or_else(|| BeaconChainError::NoProposerForSlot(column_slot))?;
   701→
   702→    let fork = epoch_proposers.fork;
   703→
   704→    // Signature verify the signed block header.
   705→    let signature_is_valid = {
   706→        let pubkey_cache = get_validator_pubkey_cache(chain)
   707→            .map_err(|_| GossipDataColumnError::PubkeyCacheTimeout)?;
   708→
   709→        let pubkey = pubkey_cache
   710→            .get(proposer_index)
   711→            .ok_or_else(|| GossipDataColumnError::UnknownValidator(proposer_index as u64))?;
   712→        let signed_block_header = &data_column.signed_block_header;
   713→        signed_block_header.verify_signature::<T::EthSpec>(
   714→            pubkey,
   715→            &fork,
   716→            chain.genesis_validators_root,
   717→            &chain.spec,
   718→        )
   719→    };
   720→
   721→    if !signature_is_valid {
   722→        return Err(GossipDataColumnError::ProposalSignatureInvalid);
   723→    }
   724→
   725→    let column_proposer_index = data_column.block_proposer_index();
   726→    if proposer_index != column_proposer_index as usize {
   727→        return Err(GossipDataColumnError::ProposerIndexMismatch {
   728→            sidecar: column_proposer_index as usize,
   729→            local: proposer_index,
   730→        });
   731→    }
   732→
   733→    Ok(())
   734→}
   735→
   736→fn verify_index_matches_subnet<E: EthSpec>(
   737→    data_column: &DataColumnSidecar<E>,
   738→    subnet: DataColumnSubnetId,
   739→    spec: &ChainSpec,
   740→) -> Result<(), GossipDataColumnError> {
   741→    let expected_subnet = DataColumnSubnetId::from_column_index(data_column.index, spec);
   742→    if expected_subnet != subnet {
   743→        return Err(GossipDataColumnError::InvalidSubnetId {
   744→            received: subnet.into(),
   745→            expected: expected_subnet.into(),
   746→        });
   747→    }
   748→    Ok(())
   749→}
   750→
   751→fn verify_slot_greater_than_latest_finalized_slot<T: BeaconChainTypes>(
   752→    chain: &BeaconChain<T>,
   753→    column_slot: Slot,
   754→) -> Result<(), GossipDataColumnError> {
   755→    let latest_finalized_slot = chain
   756→        .head()
   757→        .finalized_checkpoint()
   758→        .epoch
   759→        .start_slot(T::EthSpec::slots_per_epoch());
   760→    if column_slot <= latest_finalized_slot {
   761→        return Err(GossipDataColumnError::PastFinalizedSlot {
   762→            column_slot,
   763→            finalized_slot: latest_finalized_slot,
   764→        });
   765→    }
   766→    Ok(())
   767→}
   768→
   769→fn verify_sidecar_not_from_future_slot<T: BeaconChainTypes>(
   770→    chain: &BeaconChain<T>,
   771→    column_slot: Slot,
   772→) -> Result<(), GossipDataColumnError> {
   773→    let latest_permissible_slot = chain
   774→        .slot_clock
   775→        .now_with_future_tolerance(chain.spec.maximum_gossip_clock_disparity())
   776→        .ok_or(BeaconChainError::UnableToReadSlot)?;
   777→    if column_slot > latest_permissible_slot {
   778→        return Err(GossipDataColumnError::FutureSlot {
   779→            message_slot: column_slot,
   780→            latest_permissible_slot,
   781→        });
   782→    }
   783→    Ok(())
   784→}
   785→
   786→pub fn observe_gossip_data_column<T: BeaconChainTypes>(
   787→    data_column_sidecar: &DataColumnSidecar<T::EthSpec>,
   788→    chain: &BeaconChain<T>,
   789→) -> Result<(), GossipDataColumnError> {
   790→    // Now the signature is valid, store the proposal so we don't accept another data column sidecar
   791→    // with the same `ColumnIndex`.  It's important to double-check that the proposer still
   792→    // hasn't been observed so we don't have a race-condition when verifying two blocks
   793→    // simultaneously.
   794→    //
   795→    // Note: If this DataColumnSidecar goes on to fail full verification, we do not evict it from the
   796→    // seen_cache as alternate data_column_sidecars for the same identifier can still be retrieved over
   797→    // rpc. Evicting them from this cache would allow faster propagation over gossip. So we
   798→    // allow retrieval of potentially valid blocks over rpc, but try to punish the proposer for
   799→    // signing invalid messages. Issue for more background
   800→    // https://github.com/ethereum/consensus-specs/issues/3261
   801→    if chain
   802→        .observed_column_sidecars
   803→        .write()
   804→        .observe_sidecar(data_column_sidecar)
   805→        .map_err(|e| GossipDataColumnError::BeaconChainError(Box::new(e.into())))?
   806→    {
   807→        return Err(GossipDataColumnError::PriorKnown {
   808→            proposer: data_column_sidecar.block_proposer_index(),
   809→            slot: data_column_sidecar.slot(),
   810→            index: data_column_sidecar.index,
   811→        });
   812→    }
   813→    Ok(())
   814→}
   815→
   816→#[cfg(test)]
   817→mod test {
   818→    use crate::data_column_verification::{
   819→        GossipDataColumnError, validate_data_column_sidecar_for_gossip,
   820→    };
   821→    use crate::observed_data_sidecars::Observe;
   822→    use crate::test_utils::BeaconChainHarness;
   823→    use types::{DataColumnSidecar, DataColumnSubnetId, EthSpec, ForkName, MainnetEthSpec};
   824→
   825→    type E = MainnetEthSpec;
   826→
   827→    #[tokio::test]
   828→    async fn empty_data_column_sidecars_fails_validation() {
   829→        let spec = ForkName::Fulu.make_genesis_spec(E::default_spec());
   830→        let harness = BeaconChainHarness::builder(E::default())
   831→            .spec(spec.into())
   832→            .deterministic_keypairs(64)
   833→            .fresh_ephemeral_store()
   834→            .mock_execution_layer()
   835→            .build();
   836→        harness.advance_slot();
   837→
   838→        let slot = harness.get_current_slot();
   839→        let state = harness.get_current_state();
   840→        let ((block, _blobs_opt), _state) = harness
   841→            .make_block_with_modifier(state, slot, |block| {
   842→                *block.body_mut().blob_kzg_commitments_mut().unwrap() = vec![].into();
   843→            })
   844→            .await;
   845→
   846→        let index = 0;
   847→        let column_sidecar = DataColumnSidecar::<E> {
   848→            index,
   849→            column: vec![].into(),
   850→            kzg_commitments: vec![].into(),
   851→            kzg_proofs: vec![].into(),
   852→            signed_block_header: block.signed_block_header(),
   853→            kzg_commitments_inclusion_proof: block
   854→                .message()
   855→                .body()
   856→                .kzg_commitments_merkle_proof()
   857→                .unwrap(),
   858→        };
   859→
   860→        let result = validate_data_column_sidecar_for_gossip::<_, Observe>(
